<?php require_once __DIR__.'/bootstrap.php';auth();$rows=[];$err='';try{$rows=db()->query('SELECT * FROM subscribers ORDER BY id DESC')->fetchAll();}catch(Throwable $e){$err='جدول subscribers پیدا نشد؛ فایل database.sql را بررسی کنید.';}head('اعضای خبرنامه');if($err)echo '<p class="error">'.h($err).'</p>';?><section class="panel"><h2>ایمیل‌های ثبت‌شده (<?=count($rows)?>)</h2><div class="tablewrap"><table><tr><th>ردیف</th><th>ایمیل</th><th>تاریخ عضویت</th></tr><?php foreach($rows as $i=>$r):?><tr><td><?=$i+1?></td><td><?=h($r['email']??$r['subscriber_email']??'')?></td><td><?=h($r['created_at']??$r['subscribed_at']??'—')?></td></tr><?php endforeach;?><?php if(!$rows&&!$err):?><tr><td colspan="3">هنوز عضوی ثبت نشده است.</td></tr><?php endif;?></table></div><p class="muted">این صفحه فقط ایمیل‌ها را نمایش می‌دهد.</p></section><?php foot();?>
